mapper.select:
SELECT DISTINCT a.source_organization_id 

AND a.scheduled_date >= #{start}
AND a.scheduled_date <= #{end}
ORDER BY 1 LIMIT #{limit}

SELECT 
FROM learn_task_assignment a JOIN sys_organization org ON org.id=a.source_organization_id
WHERE 
GROUP BY a.source_organization_id,org.organization_path,org.organization_name
HAVING MAX(a.id) > #{cursor}
ORDER BY MAX(a.id) LIMIT #{limit}
